mapper.select:
SELECT c.id,c.owner_id,c.status,c.revision,c.current_version_id,c.version_number,c.created_at,c.updated_at
FROM memory_card c WHERE c.owner_id=#{owner}
  AND EXISTS (SELECT 1 FROM memory_card_source s WHERE s.owner_id=c.owner_id AND s.card_id=c.id
    AND s.version_id=c.current_version_id AND s.knowledge_item_id=#{itemId})
AND c.id > #{after}
ORDER BY c.id LIMIT #{limit}

mapper.update:
UPDATE memory_review_gate SET revision=#{gate.revision},review_required=#{gate.reviewRequired},
  last_review_decision_id=#{gate.lastReviewDecisionId},last_history_sequence=#{gate.lastHistorySequence},updated_at=#{gate.updatedAt}
WHERE owner_id=#{owner} AND card_id=#{gate.cardId} AND revision=#{expected} AND revision < 9007199254740991

mapper.select:
SELECT sequence_number AS sequence,snapshot_json FROM memory_source_history WHERE owner_id=#{owner} AND card_id=#{id}
AND sequence_number < #{before}
ORDER BY sequence_number DESC LIMIT #{limit}

SELECT card_id,revision,cycle_id,status,pause_reason,algorithm_version,parameter_version,phase,step,
  stability,difficulty,suggested_due_at,last_review_at,defer_until,last_rated_event_id,last_history_sequence,created_at,updated_at
FROM memory_schedule WHERE owner_id=#{owner} AND card_id=#{id}

SELECT sequence_number AS sequence,snapshot_json FROM memory_schedule_history WHERE owner_id=#{owner} AND card_id=#{id}
AND sequence_number < #{before}
ORDER BY sequence_number DESC LIMIT #{limit}

mapper.update:
UPDATE memory_review_settings SET revision=#{value.revision},zone_id=#{value.zoneId},daily_new_budget=#{value.dailyNewBudget},
  daily_review_budget=#{value.dailyReviewBudget},updated_at=#{value.updatedAt}
WHERE owner_id=#{owner} AND revision=#{expected} AND revision < 9007199254740991
